t("Shadowblade", "Shadowblade", "birth descriptor name")
t("Shadowblades are Rogues that are touched by the gift of magic, able to kill with their daggers under a veil of stealth while casting spells to enhance their performance and survival.", "Shadowblades are Rogues that are touched by the gift of magic, able to kill with their daggers under a veil of stealth while casting spells to enhance their performance and survival.", "_t")
t("Their use of magic is innate and not really studied; as such they do not naturally regenerate mana and must use external means of recharging.", "Their use of magic is innate and not really studied; as such they do not naturally regenerate mana and must use external means of recharging.", "_t")
t("They use the schools of Phantasm, Temporal, Divination and Conveyance magic to enhance their arts.", "They use the schools of Phantasm, Temporal, Divination and Conveyance magic to enhance their arts.", "_t")
t("Their most important stats are: Dexterity, Cunning and Magic", "Their most important stats are: Dexterity, Cunning and Magic", "_t")
